(function(){
 'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const categories=[['all','全部配件','ALL PARTS','M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z'],['tires','轮胎','TIRES','M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm0 5a5 5 0 1 0 0 10 5 5 0 0 0 0-10Z'],['wheels','轮毂','WHEELS','M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20ZM12 12V3m0 9 8-5m-8 5 5 8m-5-8-5 8m5-8-8-5'],['seats','赛车座椅','SEATS','M8 2h7l2 4-2 8 4 4v3H5v-4l3-3L6 6l2-4Zm0 12h7'],['steering','方向盘','STEERING','M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20ZM3 10h6l3 3 3-3h6M12 13v9'],['brakes','制动系统','BRAKES','M12 3a9 9 0 1 0 9 9M12 8a4 4 0 1 0 4 4M14 2h6v8h-6z'],['suspension','悬架调校','SUSPENSION','M12 2v3m0 14v3M7 5l10 3-10 3 10 3-10 3 10 2'],['safety','安全装备','SAFETY','m12 2 8 3v6c0 5-4 8-8 11-4-3-8-6-8-11V5l8-3Zm-4 9 3 3 5-6'],['electronics','数据仪表','ELECTRONICS','M3 5h18v14H3zM6 15l4-5 4 3 4-5']];
 const names=Object.fromEntries(categories.map(c=>[c[0],c[1]]));
 const ico=path=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>`;
 let context=null,limit=16;
 const concepts=[['aurora-formula-core','Formula Core','方程式 · 标准按键','formula-carbon',6800,'碳纤维面板 · 彩色仪表布局'],['aurora-formula-pro','Formula Pro','方程式 · 扩展控制','formula-carbon',9800,'碳纤维面板 · 扩展按键与拨片方案'],['aurora-gt-leather','GT Leather','GT · 打孔皮革','gt-leather',2680,'D 型轮廓 · 打孔皮革 · 紫色缝线'],['aurora-gt-bespoke','GT Bespoke','GT · 个性定制','gt-leather',3680,'D 型轮廓 · 握把尺寸与缝线定制'],['aurora-rally-core','Rally Core','拉力 · 翻毛皮','rally-suede',1980,'圆形深盘 · 翻毛皮 · 绿色中位标'],['aurora-rally-bespoke','Rally Bespoke','拉力 · 个性定制','rally-suede',2980,'握持面料、辐条饰面与中位标定制']].map(([id,name,model,image,price,structure])=>({id,brand:'AURORA',name,model,fit:'按赛车接口与尺寸定制',car:'custom',category:'steering',image:'assets/aurora-products/'+image+'.webp',price,type:'AURORA DESIGN',use:'track',unit:'只',structure,adjust:'按需求配置',desc:'极光方向盘定制设计方案。图示为 AI 辅助设计概念，握把、按键与接口配置需经设计和制造评审后确认。',source:'',priceBasis:'定制方案参考预算，实际报价按配置确认',concept:true}));
 function categoryLabel(id){return names[id]||'性能配件'}
 function filtered(c){const f=c.state.filters;let list=c.products.filter(p=>(!f.category||f.category==='all'||p.category===f.category)&&(!f.brand||f.brand==='all'||p.brand===f.brand)&&(f.car==='all'||p.car===f.car)&&(f.use==='all'||p.use===f.use||p.use==='mixed')&&(f.budget==='all'||p.price<=+f.budget)&&`${p.name} ${p.brand} ${p.model} ${p.fit} ${categoryLabel(p.category)}`.toLowerCase().includes(f.search.toLowerCase().trim()));if(!f.sort||f.sort==='featured'){const order=['steering','tires','wheels','seats','suspension','brakes','safety','electronics'];const buckets=order.map(cat=>list.filter(p=>p.category===cat).sort((a,b)=>Number(!!b.concept)-Number(!!a.concept)));const mixed=[];while(buckets.some(b=>b.length))for(const b of buckets)if(b.length)mixed.push(b.shift());list=mixed}if(f.sort==='price-low')list.sort((a,b)=>a.price-b.price);if(f.sort==='price-high')list.sort((a,b)=>b.price-a.price);if(f.sort==='brand')list.sort((a,b)=>a.brand.localeCompare(b.brand));return list}
 function card(p,c){const chosen=c.state.compare.includes(p.id);return `<article class="product-card store-product" data-product-id="${p.id}"><button class="product-image" data-action="details" data-id="${p.id}" aria-label="查看 ${esc(p.brand+' '+p.name)}"><span class="number">${esc(categoryLabel(p.category))}</span><img src="${esc(p.image)}" alt="${esc(p.brand+' '+p.name+(p.concept?' · 设计概念':''))}" loading="lazy" decoding="async"><span class="product-tag">${p.concept?'设计概念':esc(p.type||'PERFORMANCE PARTS')}</span><span class="store-quick">查看详情 ↗</span></button><div class="product-body"><div class="product-brand">${esc(p.brand)}</div><h3><button data-action="details" data-id="${p.id}">${esc(p.name)}</button></h3><div class="store-model">${esc(p.model)}</div><div class="product-meta">${esc(p.fit)}</div><div class="product-price">¥${Math.round(p.price).toLocaleString('zh-CN')} <small>/ ${esc(p.unit||'套')} · 参考</small></div><div class="product-actions"><button class="button ghost" data-action="compare" data-id="${p.id}" aria-pressed="${chosen}">${c.icon(chosen?'check':'compare')}${chosen?'已选对比':'规格对比'}</button><button class="round-add" data-action="add" data-id="${p.id}" aria-label="将 ${esc(p.name)} 加入清单">${c.icon('plus')}</button></div></div></article>`}
 function homeCategories(products){return `<section class="department-strip container"><div class="department-intro"><small>BUILT FOR YOUR DRIVE</small><strong>从热爱出发，按系统选配。</strong></div><div class="department-links">${categories.slice(1).map(([id,cn,en,path])=>`<a href="#shop" data-store-category="${id}">${ico(path)}<b>${cn}</b><small>${en}</small></a>`).join('')}</div></section>`}
 function customBanner(){return `<section class="container aurora-custom-section"><div class="aurora-custom-banner"><div class="custom-orbits" aria-hidden="true"><i></i><i></i></div><div class="custom-copy"><span class="eyebrow">AURORA DESIGN STUDIO</span><h2>每一次转向，<br>都有你的表达。</h2><p>从方程式握把，到专属缝线。<br>一起定义属于你的方向盘。</p><a class="button primary" href="#shop" data-store-brand="AURORA">探索极光定制 ${ico('M4 12h16m-6-6 6 6-6 6')}</a><small>设计概念 · 按需配置</small></div><div class="custom-product-display"><img src="assets/aurora-products/formula-carbon.webp" alt="Aurora 碳纤维方向盘设计概念" loading="lazy"><span class="custom-image-caption">FORMULA CORE <b>AURORA / CUSTOM SERIES</b></span></div></div></section>`}
 function render(c){context=c;limit=16;const brands=[...new Set(c.products.map(p=>p.brand))].sort();return `<div class="container store-page"><header class="store-header"><div><div class="eyebrow">THE PERFORMANCE COLLECTION</div><h1>装备你的下一程。</h1><p>从公路到赛道，从整车姿态到指尖触感。</p></div><div class="store-index"><strong>${c.products.length}<small>SKU</small></strong><span>八大系统 · 精选配件<small>CURATED FOR THE DRIVE</small></span></div></header><div class="store-category-nav" aria-label="配件分类">${categories.map(([id,cn,en,path])=>`<button data-store-category="${id}" aria-pressed="${(c.state.filters.category||'all')===id}" class="${(c.state.filters.category||'all')===id?'active':''}">${ico(path)}<span><b>${cn}</b><small>${en}</small></span><em>${id==='all'?c.products.length:c.products.filter(p=>p.category===id).length}</em></button>`).join('')}</div><div class="store-toolbar filters"><div class="store-search">${c.icon('chart')}<input id="product-search" type="search" aria-label="搜索配件" placeholder="搜索品牌、型号、尺寸或配件" value="${esc(c.state.filters.search)}"></div><label>品牌<select id="filter-brand"><option value="all">全部品牌</option>${brands.map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join('')}</select></label><label>车型<select id="filter-car"><option value="all">全部车型</option><option value="f87">BMW M2 F87</option><option value="z28">Camaro Z/28</option><option value="universal">按尺寸 / 接口适配</option><option value="custom">定制方案</option></select></label><label>预算<select id="filter-budget"><option value="all">不限预算</option><option value="2000">¥2,000 以内</option><option value="5000">¥5,000 以内</option><option value="10000">¥10,000 以内</option><option value="20000">¥20,000 以内</option></select></label><label>用途<select id="filter-use"><option value="all">全部用途</option><option value="street">公路 / 赛道日</option><option value="track">赛道 / 竞赛</option></select></label><button class="text-button" data-action="reset-filters">重置</button></div><div class="store-results-bar"><span id="store-result-count"></span><label>排序 <select id="filter-sort"><option value="featured">精选顺序</option><option value="price-low">价格从低到高</option><option value="price-high">价格从高到低</option><option value="brand">品牌名称</option></select></label></div><div class="product-grid shop-grid store-grid" id="shop-products"></div><div id="store-load-more"></div><div class="store-pricing-note">参考价格用于选型预算，按所示计价单位展示。实际报价、配置、适配与交期需核实。品牌资料可在商品详情查看。</div><div id="compare-tray"></div></div>`}
 function refresh(c){context=c;const list=filtered(c);const el=document.querySelector('#shop-products');if(!el)return;el.innerHTML=list.length?list.slice(0,limit).map(p=>card(p,c)).join(''):'<div class="empty-state">没有找到符合条件的配件。<br><button class="text-button" data-action="reset-filters">清除筛选 →</button></div>';document.querySelector('#store-result-count').innerHTML=`<strong>${categoryLabel(c.state.filters.category||'all')}</strong><span>${list.length} 款选型 · 已显示 ${Math.min(limit,list.length)} 款</span>`;document.querySelector('#store-load-more').innerHTML=list.length>limit?`<button class="button ghost" data-store="more">继续浏览 · 还有 ${list.length-limit} 款 ${c.icon('plus')}</button>`:list.length?'<span>已展示全部结果</span>':'';document.querySelectorAll('.store-category-nav [data-store-category]').forEach(b=>{const active=b.dataset.storeCategory===(c.state.filters.category||'all');b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelector('#compare-tray').innerHTML=c.state.compare.length?`<div class="compare-tray"><p>已选 <b>${c.state.compare.length}</b> 款 · ${c.state.compare.map(id=>esc(c.products.find(p=>p.id===id)?.brand||'')).join(' / ')}</p><button class="text-button" data-action="clear-compare">清空</button><button class="button primary small" data-store="compare-open">查看规格对比 ${c.icon('arrow')}</button></div>`:''}
 function detail(p,c){const facts=[['分类',categoryLabel(p.category)],['型号 / 规格',p.model],['适配要求',p.fit],['结构 / 材料',p.structure],['配置 / 调节',p.adjust],['计价单位',p.unit||'套']];c.modal(p.brand+' · '+p.name,`<div class="store-detail-grid"><div class="store-detail-image"><img src="${esc(p.image)}" alt="${esc(p.name)}">${p.concept?'<span>AI 辅助设计概念</span>':''}</div><div><div class="eyebrow">${p.concept?'AURORA DESIGN STUDIO':esc(p.type||'CURATED PARTS')}</div><h3>${esc(p.name)}</h3><div class="product-price">¥${Math.round(p.price).toLocaleString('zh-CN')}<small> / ${esc(p.unit||'套')} · 参考预算</small></div><p>${esc(p.desc)}</p><dl>${facts.filter(f=>f[1]).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${p.source?`<a class="text-button" target="_blank" rel="noopener noreferrer" href="${esc(p.source)}">品牌官方资料 ↗</a>`:'<span class="caption">设计方案以确认后的图纸与配置为准</span>'}</div></div><p class="store-detail-note">${esc(p.priceBasis||'参考预算，实际报价按具体型号、配置和服务确认。')}${p.sourcePrice?' · 来源标价 '+esc(p.sourceCurrency||'')+' '+esc(p.sourcePrice):''}</p>`,`<button class="button ghost" data-action="compare" data-id="${p.id}">加入规格对比</button><button class="button primary" data-action="add" data-id="${p.id}">加入选购清单 ${c.icon('plus')}</button>`)}
 function compare(c){const list=c.products.filter(p=>c.state.compare.includes(p.id));if(!list.length)return;const rows=[['产品',p=>p.name],['规格',p=>p.model],['配件系统',p=>categoryLabel(p.category)],['参考预算',p=>'¥'+p.price.toLocaleString('zh-CN')+' / '+(p.unit||'套')],['适配要求',p=>p.fit],['结构 / 材料',p=>p.structure||'以品牌资料为准'],['配置 / 调节',p=>p.adjust||'以品牌资料为准']];c.modal('规格对比',`<div class="store-compare-table"><table><thead><tr><th>比较维度</th>${list.map(p=>`<th><img src="${esc(p.image)}" alt="${esc(p.name)}"><strong>${esc(p.brand)}</strong></th>`).join('')}</tr></thead><tbody>${rows.map(([name,fn])=>`<tr><th>${name}</th>${list.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="caption">不同类别与应用尺寸分别核对，价格按各自单位展示。</p>`,list.some(p=>['ohlins','kw','dssv'].includes(p.id))?'<button class="button primary" data-store="go-lab">打开悬架性能模型 →</button>':'<button class="button primary" data-action="go-service">整理适配需求 →</button>');document.querySelector('#modal').classList.add('store-compare-dialog')}
 function selectCategory(id){if(!context)return;context.state.filters.category=id;context.state.filters.brand='all';limit=16;if(location.hash==='#shop'){document.querySelector('#filter-brand').value='all';refresh(context)}else location.hash='shop'}
 function mount(c){context=c;['brand','sort','car','budget','use'].forEach(k=>{const el=document.querySelector('#filter-'+k);if(el)el.value=c.state.filters[k]||(k==='sort'?'featured':'all')})}
 document.addEventListener('click',e=>{const category=e.target.closest('[data-store-category]');if(category){e.preventDefault();selectCategory(category.dataset.storeCategory);return}const brand=e.target.closest('[data-store-brand]');if(brand&&context){e.preventDefault();context.state.filters.category='all';context.state.filters.brand=brand.dataset.storeBrand;limit=16;if(location.hash==='#shop'){document.querySelector('#filter-brand').value=brand.dataset.storeBrand;refresh(context)}else location.hash='shop';return}const b=e.target.closest('[data-store]');if(!b||!context)return;if(b.dataset.store==='more'){limit+=16;refresh(context)}if(b.dataset.store==='compare-open')compare(context);if(b.dataset.store==='go-lab'){document.querySelector('#modal').close();location.hash='lab'}});
 window.AuroraStore={concepts,categories,categoryLabel,render,refresh,card,detail,filtered,homeCategories,customBanner,mount,resetLimit:()=>{limit=16},inspect:()=>({total:context?.products.length,filtered:context?filtered(context).length:0,limit})};
})();
